"""Version-1 SecMan integration-result client and GitHub finding mapper.

This is the opt-in transport selected by ``SECMAN_SCANNER_ID``.  The legacy
``cli-add`` integration remains in :mod:`secscan.secman_push`.
"""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any, Iterable, Mapping
from urllib.parse import urlsplit, urlunsplit

import requests

from . import dryrun
from .findings import Finding
from .github_app import RepoInfo

_TIMEOUT_S = 30
_CONFIDENCE = {"high": 0.9, "medium": 0.7, "low": 0.5}
_TERMINAL_WITHOUT_FINDINGS = {"FAILED", "SKIPPED"}


class IntegrationResultError(Exception):
    """Raised when the version-1 API rejects or cannot decode a request."""


@dataclass(frozen=True)
class IntegrationSubject:
    id: int
    scanner_id: int
    asset_id: int
    github_repository_id: int | None
    name: str
    uri: str | None
    owner: str | None
    github_instance: str | None
    github_repo_id: int | None

    @classmethod
    def from_api(cls, value: Mapping[str, Any]) -> "IntegrationSubject":
        return cls(
            id=int(value["id"]),
            scanner_id=int(value["scannerId"]),
            asset_id=int(value["assetId"]),
            github_repository_id=_optional_int(value.get("githubRepositoryId")),
            name=str(value["name"]),
            uri=_optional_str(value.get("uri")),
            owner=_optional_str(value.get("owner")),
            github_instance=_optional_str(value.get("githubInstance")),
            github_repo_id=_optional_int(value.get("githubRepoId")),
        )


@dataclass(frozen=True)
class IntegrationContext:
    scanner_id: int
    github_instance: str
    subjects: list[IntegrationSubject]
    client: "IntegrationClient"


def _optional_int(value: Any) -> int | None:
    return None if value is None else int(value)


def _optional_str(value: Any) -> str | None:
    return None if value is None else str(value)


def validate_base_url(value: str | None) -> str:
    """Validate an operator-configured SecMan origin and remove a trailing slash."""
    if not value:
        raise IntegrationResultError("secman URL must be an absolute https URL")
    parts = urlsplit(value.strip())
    if parts.scheme != "https" or not parts.hostname:
        raise IntegrationResultError("secman URL must be an absolute https URL")
    if parts.username or parts.password or parts.query or parts.fragment:
        raise IntegrationResultError("secman URL must not contain credentials, query, or fragment")
    return urlunsplit((parts.scheme, parts.netloc, parts.path.rstrip("/"), "", ""))


def _github_instance(value: str | None) -> str | None:
    """Canonical host identity for public GitHub, GHE Cloud, or GHES."""
    if not value:
        return None
    raw = value.strip()
    parts = urlsplit(raw if "://" in raw else f"https://{raw}")
    if parts.scheme.lower() != "https":
        return None
    host = (parts.hostname or "").lower()
    if not host:
        return None
    if host == "api.github.com":
        host = "github.com"
    elif host.startswith("api.") and host.endswith(".ghe.com"):
        host = host[len("api.") :]
    port = f":{parts.port}" if parts.port and parts.port != 443 else ""
    return f"{host}{port}"


def subject_repository_full_name(subject: IntegrationSubject) -> str | None:
    if subject.uri:
        parts = urlsplit(subject.uri)
        segments = [part for part in parts.path.strip("/").split("/") if part]
        if len(segments) == 2:
            return f"{segments[0]}/{segments[1].removesuffix('.git')}".lower()
    return subject.name.lower() if subject.name.count("/") == 1 else None


def same_github_instance(left: str | None, right: str | None) -> bool:
    """Whether two GitHub instance URLs name the same canonical HTTPS host."""
    canonical = _github_instance(left)
    return canonical is not None and canonical == _github_instance(right)


def match_subject(
    subjects: Iterable[IntegrationSubject],
    repo: RepoInfo,
    github_instance: str,
) -> IntegrationSubject | None:
    """Find the permitted subject for a repository without crossing GitHub instances."""
    wanted_name = repo.full_name.lower()
    for subject in subjects:
        if not same_github_instance(subject.github_instance, github_instance):
            continue
        if subject.github_repo_id is not None:
            if repo.github_repo_id == subject.github_repo_id:
                return subject
            continue
        if subject_repository_full_name(subject) == wanted_name:
            return subject
    return None


def finding_external_id(finding: Finding) -> str:
    """Stable rule/location identity, intentionally excluding mutable presentation."""
    category = finding.category.strip().lower() or "uncategorized"
    path = finding.file_path.strip().replace("\\", "/")
    location = finding.line_range.strip()
    digest = hashlib.sha256(f"{category}|{path}|{location}".encode()).hexdigest()
    return f"secscan:{digest}"


def _finding_body(
    finding: Finding,
    *,
    engine: str | None,
    model: str | None,
    commit_sha: str | None,
    issue_urls: Mapping[str, str],
    fix_pr_url: str | None,
) -> dict[str, Any]:
    external_id = finding_external_id(finding)
    return {
        "externalId": external_id,
        "legacyIds": [],
        "severity": finding.severity.value.upper(),
        "title": finding.title,
        "description": finding.description,
        "recommendation": finding.recommendation,
        "evidence": finding.description,
        "filePath": finding.file_path or None,
        "lineRange": finding.line_range or None,
        "url": None,
        "confidence": _CONFIDENCE.get(finding.confidence.strip().lower(), 0.7),
        "engine": engine,
        "model": model,
        "commitSha": commit_sha,
        "issueUrl": issue_urls.get(external_id),
        "fixPrUrl": fix_pr_url,
        "attachments": [],
    }


def build_run_body(
    *,
    scanner_id: int,
    subject: IntegrationSubject,
    status: str,
    findings: Iterable[Finding],
    started_at: str,
    completed_at: str,
    metadata: Mapping[str, Any] | None = None,
    engine: str | None = None,
    model: str | None = None,
    commit_sha: str | None = None,
    issue_urls: Mapping[str, str] | None = None,
    fix_pr_url: str | None = None,
) -> dict[str, Any]:
    """Build a deterministic version-1 terminal snapshot.

    Secscan reports only High/Critical findings, so it can never truthfully
    claim complete subject coverage.  Failed and skipped runs carry no findings.
    """
    normalized_status = status.upper()
    if normalized_status not in {"SUCCESS", "PARTIAL", "FAILED", "SKIPPED"}:
        raise IntegrationResultError(f"unsupported integration run status: {status}")
    if subject.scanner_id != scanner_id:
        raise IntegrationResultError("integration subject belongs to a different scanner")
    finding_list = list(findings)
    if len(finding_list) > 500:
        raise IntegrationResultError("integration run exceeds the 500 finding limit")
    mapped = [] if normalized_status in _TERMINAL_WITHOUT_FINDINGS else [
        _finding_body(
            finding,
            engine=engine,
            model=model,
            commit_sha=commit_sha,
            issue_urls=issue_urls or {},
            fix_pr_url=fix_pr_url,
        )
        for finding in finding_list
    ]
    mapped.sort(key=lambda finding: finding["externalId"])
    external_ids = [finding["externalId"] for finding in mapped]
    if len(external_ids) != len(set(external_ids)):
        raise IntegrationResultError("integration run contains duplicate finding identities")
    body: dict[str, Any] = {
        "scannerId": scanner_id,
        "subjectId": subject.id,
        "status": normalized_status,
        "completeCoverage": False,
        "startedAt": started_at,
        "completedAt": completed_at,
        "metadataJson": json.dumps(metadata or {}, sort_keys=True, separators=(",", ":")),
        "findings": mapped,
"""Version-1 SecMan integration-result client for web-security scans."""

from __future__ import annotations

import hashlib
import json
import ssl
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from datetime import datetime
from typing import Any, Self
from urllib.parse import urlsplit, urlunsplit

import httpx
import truststore

from .models import DetectedComponent, ExposureObservation, Finding, TargetResult
from .targets import NormalizedTarget, TargetError, normalize_target

_TIMEOUT_SECONDS = 30.0


def _system_ca_context() -> ssl.SSLContext:
    """Use the native OS trust store while retaining TLS and hostname verification."""
    return truststore.SSLContext(ssl.PROTOCOL_TLS_CLIENT)


class SecmanIntegrationError(RuntimeError):
    """Raised when the SecMan integration contract cannot be satisfied."""


class AmbiguousSubject(SecmanIntegrationError):
    """Raised when a target does not map to exactly one authorized subject."""


@dataclass(frozen=True, slots=True)
class IntegrationSubject:
    id: int
    scanner_id: int
    asset_id: int
    name: str
    uri: str | None
    cloud_account_id: str | None = None

    @classmethod
    def from_api(cls, value: Mapping[str, Any]) -> IntegrationSubject:
        try:
            return cls(
                id=int(value["id"]),
                scanner_id=int(value["scannerId"]),
                asset_id=int(value["assetId"]),
                name=str(value["name"]),
                uri=None if value.get("uri") is None else str(value["uri"]),
                cloud_account_id=(
                    None if value.get("cloudAccountId") is None else str(value["cloudAccountId"])
                ),
            )
        except (KeyError, TypeError, ValueError) as error:
            raise SecmanIntegrationError(
                "SecMan returned an invalid integration subject"
            ) from error


def validate_base_url(value: str) -> str:
    """Accept only an absolute HTTPS origin without embedded credentials."""
    parts = urlsplit(value.strip())
    if parts.scheme != "https" or not parts.hostname:
        raise SecmanIntegrationError("SecMan URL must be an absolute HTTPS URL")
    if parts.username or parts.password or parts.query or parts.fragment:
        raise SecmanIntegrationError(
            "SecMan URL must not contain credentials, a query, or a fragment"
        )
    return urlunsplit((parts.scheme, parts.netloc, parts.path.rstrip("/"), "", ""))


def match_subject(
    subjects: Iterable[IntegrationSubject],
    target_url: str,
    *,
    aws_account_number: str | None = None,
) -> IntegrationSubject | None:
    """Match by AWS account when supplied, then canonical URL or hostname."""
    available = tuple(subjects)
    if aws_account_number is not None:
        available = tuple(
            subject for subject in available if subject.cloud_account_id == aws_account_number
        )
    target = urlsplit(target_url)
    exact = tuple(
        subject
        for subject in available
        if subject.uri and subject.uri.rstrip("/") == target_url.rstrip("/")
    )
    if len(exact) > 1:
        raise AmbiguousSubject("multiple SecMan subjects match the target URI")
    if exact:
        return exact[0]
    hostname = tuple(
        subject for subject in available if subject.name.lower() == (target.hostname or "").lower()
    )
    if len(hostname) > 1:
        raise AmbiguousSubject("multiple SecMan subjects match the target hostname")
    return hostname[0] if hostname else None


def _timestamp(value: datetime) -> str:
    return value.isoformat().replace("+00:00", "Z")


def _finding_body(finding: Finding) -> dict[str, Any]:
    return {
        "externalId": finding.external_id,
        "legacyIds": [],
        "severity": finding.severity.value,
        "title": finding.title,
        "description": finding.description or None,
        "recommendation": finding.recommendation or None,
        "evidence": finding.evidence or None,
        "filePath": None,
        "lineRange": None,
        "url": finding.url,
        "confidence": finding.confidence,
        "engine": finding.engine,
        "model": finding.model,
        "commitSha": None,
        "issueUrl": None,
        "fixPrUrl": None,
        "attachments": [],
    }


def _component_body(component: DetectedComponent) -> dict[str, Any]:
    return {
        "componentKey": component.component_key,
        "category": component.category.value,
        "name": component.name,
        "version": component.version,
        "confidence": component.confidence,
        "evidenceType": component.evidence_type,
        "evidence": component.evidence,
        "sourceUrl": component.source_url,
    }


def _exposure_body(exposure: ExposureObservation) -> dict[str, Any]:
    return {
        "configuredUrl": exposure.configured_url,
        "effectiveUrl": exposure.effective_url,
        "reachability": exposure.reachability.value,
        "httpStatus": exposure.http_status,
        "redirectCount": exposure.redirect_count,
        "bodyLength": exposure.body_length,
        "vantagePoint": exposure.vantage_point,
    }


def targets_from_subjects(subjects: Iterable[IntegrationSubject]) -> tuple[NormalizedTarget, ...]:
    """Convert explicitly bound SecMan subjects into scan targets without guessing URLs."""
    targets: list[NormalizedTarget] = []
    for subject in subjects:
        if subject.uri is None:
            continue
        try:
            target = normalize_target(subject.uri)
        except TargetError as error:
            raise SecmanIntegrationError(
                f"SecMan subject {subject.id} has an invalid HTTP(S) URI"
            ) from error
        targets.append(
            NormalizedTarget(
                url=target.url,
                scheme=target.scheme,
                host=target.host,
                port=target.port,
                secman_subject_id=subject.id,
                secman_asset_id=subject.asset_id,
            )
        )
    return tuple(targets)


def build_run_body(
    scanner_id: int,
    subject: IntegrationSubject,
    result: TargetResult,
    *,
    metadata: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a deterministic terminal snapshot using SecMan's version-1 schema."""
    if subject.scanner_id != scanner_id:
        raise SecmanIntegrationError("integration subject belongs to a different scanner")
    findings = (
        []
        if result.status.value == "FAILED"
        else [_finding_body(finding) for finding in result.findings]
    )
    if len(findings) > 500:
        raise SecmanIntegrationError("integration run exceeds the 500-finding limit")
    findings.sort(key=lambda finding: str(finding["externalId"]))
    external_ids = [finding["externalId"] for finding in findings]
    if len(external_ids) != len(set(external_ids)):
        raise SecmanIntegrationError("integration run contains duplicate finding identities")
    body: dict[str, Any] = {
        "scannerId": scanner_id,
        "subjectId": subject.id,
        "status": result.status.value,
        "completeCoverage": result.complete,
        "startedAt": _timestamp(result.started_at),
        "completedAt": _timestamp(result.completed_at),
        "metadataJson": json.dumps(metadata or {}, sort_keys=True, separators=(",", ":")),
        "findings": findings,
    }
    if result.exposure is not None or result.components:
        if len(result.components) > 500:
            raise SecmanIntegrationError("integration run exceeds the 500-component limit")
        body["inventory"] = {
            "completeCoverage": result.inventory_complete,
            "exposure": None if result.exposure is None else _exposure_body(result.exposure),
            "components": [
                _component_body(component)
                for component in sorted(result.components, key=lambda item: item.component_key)
            ],
        }
    canonical = json.dumps(body, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    body["runKey"] = "secman-web-check-v1:" + hashlib.sha256(canonical.encode()).hexdigest()
    return body


class IntegrationClient:
    """Authenticated client for subject discovery and atomic run submission."""

