        const val SECTION_IMPORTS = "imports"
        const val SECTION_TOP_PRODUCTS = "top-products"
        const val SECTION_TOP_SERVERS = "top-servers"
        const val SECTION_INTEGRATIONS = "integrations"

        /**
         * Every section this builder can produce. Section names are lowercase
         * with hyphens because the relay validates them against exactly that
         * character class before they reach a URL or a scope string.
         */
        val ALL_SECTIONS: List<String> = listOf(
            SECTION_TOTALS,
            SECTION_KPIS,
            SECTION_EXCEPTIONS,
            SECTION_IMPORTS,
            SECTION_TOP_PRODUCTS,
            SECTION_TOP_SERVERS,
            SECTION_INTEGRATIONS
        )

        /**
         * The role gate for each section, and the single most important table
         * in this file.
         *
         * Each entry mirrors the `@Secured` annotation on the secman controller
         * the data comes from, so a user sees on their phone exactly the
         * sections they could open in the web UI — no more, and no less:
         *
         *  - [SECTION_KPIS]       DashboardController        @Secured("ADMIN","SECCHAMPION")
         *  - [SECTION_EXCEPTIONS] VulnerabilityExceptionRequestController
         *                         .getPendingCount           @Secured("ADMIN","SECCHAMPION")
         *  - [SECTION_IMPORTS]    CrowdStrikeController      ADMIN/VULN
         *  - the remaining three are the admin summary, which is ADMIN-only.
         *
         * **When you change a controller's `@Secured`, change the matching row
         * here.** Nothing in the build can catch the drift: the relay will
         * happily enforce whatever it is told, and the result is a phone
         * showing data the web UI would refuse. `RelaySnapshotBuilderTest`
         * pins the pairs that exist today.
         */
        val SECTION_POLICIES: Map<String, RelaySectionPolicy> = mapOf(
            SECTION_TOTALS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN"),
                description = "Asset, vulnerability and user counts"
            ),
            SECTION_KPIS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN", "SECCHAMPION"),
                description = "AWS clean-server and EDR coverage KPIs"
            ),
            SECTION_EXCEPTIONS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN", "SECCHAMPION"),
                description = "Vulnerability exception requests awaiting review"
            ),
            SECTION_IMPORTS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN", "VULN"),
                description = "Freshness of the last CrowdStrike import"
            ),
            SECTION_TOP_PRODUCTS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN"),
                description = "Products with the most vulnerabilities"
            ),
            SECTION_TOP_SERVERS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN"),
                description = "Servers with the most vulnerabilities"
            ),
            SECTION_INTEGRATIONS to RelaySectionPolicy(
                requiredRoles = listOf("ADMIN"),
                description = "Integration finding counts and scan coverage freshness"
            )
        )

        /** Renders an instant as the RFC 3339 UTC string the relay parses. */
        fun rfc3339(instant: Instant): String = DateTimeFormatter.ISO_INSTANT.format(instant)

        /**
         * Renders a zone-less [LocalDateTime] as an ISO local timestamp.
         *
         * Deliberately *not* stamped with a zone: these values come out of the
         * database as LocalDateTime with no recorded offset, and inventing UTC
         * would silently shift every displayed time by the server's offset. The
         * app renders them as "server local time", which is what they are.
         */
        fun isoLocal(value: LocalDateTime?): String? =
            value?.let { DateTimeFormatter.ISO_LOCAL_DATE_TIME.format(it) }
    }

    /**
     * Builds a snapshot containing the requested [sections].
     *
     * A section whose source throws is omitted and logged rather than failing
     * the whole push: a broken KPI cache should degrade one tile in the app,
     * not blind the on-call admin to everything else.
     */
    open fun build(instanceId: String, sections: List<String>): RelaySnapshot {
        val requested = sections.ifEmpty { ALL_SECTIONS }
        val built = LinkedHashMap<String, Any>()

        for (section in requested) {
            val value = try {
                buildSection(section)
            } catch (e: Exception) {
                logger.warn("Relay snapshot section '{}' could not be built and was omitted: {}", section, e.message)
                null
            }
            if (value != null) {
                built[section] = value
            }
        }

        if (built.isEmpty()) {
            // The relay refuses an empty snapshot, so say why here rather than
            // letting it come back as an opaque 400.
            throw IllegalStateException("No relay snapshot section could be built; check secman.relay.sections")
        }

        // Every section must carry a policy or the relay refuses the whole
        // push. That is the desired failure: a section nobody can read looks
        // exactly like a broken app, and this way it surfaces here instead.
        val policy = built.keys.associateWith { name ->
            SECTION_POLICIES[name]
                ?: throw IllegalStateException("Relay section '$name' has no role policy in SECTION_POLICIES")
        }

        return RelaySnapshot(
            instanceId = instanceId,
            generatedAt = rfc3339(Instant.now()),
            sections = built,
            policy = policy
        )
    }

    private fun buildSection(section: String): Any? = when (section) {
        SECTION_TOTALS -> buildTotals()
        SECTION_KPIS -> buildKpis()
        SECTION_EXCEPTIONS -> buildExceptions()
        SECTION_IMPORTS -> buildImports()
        SECTION_TOP_PRODUCTS -> buildTopProducts()
        SECTION_TOP_SERVERS -> buildTopServers()
        SECTION_INTEGRATIONS -> buildIntegrations()
        else -> {
            logger.warn("Unknown relay snapshot section '{}' requested; ignoring", section)
            null
        }
    }

    private fun buildIntegrations(): Map<String, Any> {
        val summary = integrationReadService.globalSummary()
        return mapOf("scanners" to summary.scanners, "totalSubjects" to summary.totalSubjects,
            "healthySubjects" to summary.healthySubjects, "failedSubjects" to summary.failedSubjects,
            "unscannedSubjects" to summary.unscannedSubjects, "staleSubjects" to summary.staleSubjects,
            "openFindings" to summary.openFindings)
    }

    private fun buildTotals(): Map<String, Any> {
        val stats = adminSummaryService.getSystemStatistics()
        return mapOf(
            "assets" to stats.assetCount,
            "vulnerabilities" to stats.vulnerabilityCount,
            "users" to stats.userCount
        )
    }
    public let failedSubjects: Int
    public let unscannedSubjects: Int
    public let staleSubjects: Int
    public let openFindings: Int
}

// MARK: - Section identifiers

/// The sections `RelaySnapshotBuilder` publishes today, and the roles secman
/// gates them behind.
///
/// This table is presentation only — an icon and a title. It decides nothing:
/// authorization happens on the relay, and a section missing from this enum
/// still appears in the UI via the generic renderer. See `RelaySectionID`. The
/// role each section requires is documented in `docs/API.md`; it is not
/// mirrored here, because a copy the app never consults is a copy that drifts.
public enum RelaySection: String, CaseIterable, Sendable {
    case totals
    case kpis
    case exceptions
    case imports
    case topProducts = "top-products"
    case topServers = "top-servers"
    case integrations

    public var displayName: String {
        switch self {
        case .totals: return "Overview"
        case .kpis: return "Security KPIs"
        case .exceptions: return "Exceptions"
        case .imports: return "Imports"
        case .topProducts: return "Top products"
        case .topServers: return "Top servers"
        case .integrations: return "Integrations"
        }
    }

    public var symbolName: String {
        switch self {
        case .totals: return "square.grid.2x2"
        case .kpis: return "gauge.with.needle"
        case .exceptions: return "exclamationmark.triangle"
        case .imports: return "arrow.down.circle"
        case .topProducts: return "shippingbox"
        case .topServers: return "server.rack"
        case .integrations: return "checkmark.arrow.trianglehead.counterclockwise"
        }
    }
}

/// A section the relay says this device may read.
///
/// The name comes from the server, always. `known` is non-nil for the seven
/// sections this build renders with a purpose-built view; for anything else the
/// app still lists it and still shows its contents, just generically. That is
/// the difference between "the relay grew a section" being a release and being
/// a refresh.
public struct RelaySectionID: Hashable, Sendable, Identifiable, Comparable {
    public let name: String
    public var id: String { name }

    public init(_ name: String) {
        self.name = name
    }

    public var known: RelaySection? { RelaySection(rawValue: name) }

    public var displayName: String {
        if let known { return known.displayName }
        // "top-products" -> "Top products". Good enough for a name the app has
        // never heard of, and better than showing the raw key.
        let spaced = name.replacingOccurrences(of: "-", with: " ")
        return spaced.prefix(1).uppercased() + spaced.dropFirst()
    }

    public var symbolName: String { known?.symbolName ?? "doc.text" }

    /// Known sections first, in the canonical order above; then anything new,
    /// alphabetically. A stable order matters more than a clever one: the
    /// sidebar should not reshuffle between refreshes.
    public static func < (lhs: RelaySectionID, rhs: RelaySectionID) -> Bool {
        switch (lhs.known, rhs.known) {
        case let (l?, r?):
            let all = RelaySection.allCases
            return all.firstIndex(of: l)! < all.firstIndex(of: r)!
        case (_?, nil): return true
        case (nil, _?): return false
        case (nil, nil): return lhs.name < rhs.name
        }
    }
}

// MARK: - JSON

public enum RelayJSON {
    /// Shared coders.
    ///
    /// `nonisolated(unsafe)` rather than a fresh instance per call: these are
    /// configured once and never mutated afterwards, which is the condition
    /// under which `JSONDecoder` is safe to share, and a snapshot re-encodes up
    /// to 64 opaque section bodies per refresh.
	States      *idp.EphemeralStore
	Tickets     *idp.EphemeralStore

	// EnrollmentCodesEnabled allows the code-based path to be switched off
	// entirely in a deployment that wants federated login only.
	EnrollmentCodesEnabled bool

	Now func() time.Time
}

// Routes registers the mobile plane.
//
// Each unauthenticated route carries its own rate-limit family so that
// hammering one cannot exhaust a legitimate device's budget on another.
func (h *Handler) Routes(mux *http.ServeMux) {
	limited := func(family string, fn http.HandlerFunc) http.Handler {
		return httpx.Chain(fn, httpx.Limit(h.Limiter, family, h.Logger))
	}

	mux.Handle("GET /api/v1/providers", limited("providers", h.handleProviders))

	mux.Handle("POST /api/v1/auth/nonce", limited("login", h.handleNonce))
	mux.Handle("POST /api/v1/auth/oidc", limited("login", h.handleOIDCBind))
	mux.Handle("POST /api/v1/auth/github/start", limited("login", h.handleGitHubStart))
	mux.Handle("GET /api/v1/auth/github/callback", limited("login", h.handleGitHubCallback))
	mux.Handle("POST /api/v1/auth/github/complete", limited("login", h.handleGitHubComplete))
	mux.Handle("POST /api/v1/enroll", limited("enroll", h.handleEnroll))

	mux.Handle("POST /api/v1/auth/challenge", limited("challenge", h.handleChallenge))
	mux.Handle("POST /api/v1/auth/token", limited("token", h.handleToken))

	mux.Handle("GET /api/v1/meta", h.authenticated(h.handleMeta))
	mux.Handle("GET /api/v1/status", h.authenticated(h.handleStatus))
	mux.Handle("GET /api/v1/status/{section}", h.authenticated(h.handleSection))
	mux.Handle("GET /api/v1/session", h.authenticated(h.handleSession))
}

// --- discovery --------------------------------------------------------------

type providersResponse struct {
	Providers []string `json:"providers"`
	// EnrollmentCodes reports whether the typed-code path is available at all.
	EnrollmentCodes bool `json:"enrollmentCodes"`
	// PrivilegedRoles and StrongProviders let the app explain, before the user
	// picks a button, that an admin account cannot be bound by a weak method.
	// Publishing the policy is not a leak — it is the same rule the relay will
	// enforce anyway, and stating it up front avoids a confusing 403.
	PrivilegedRoles []string `json:"privilegedRoles"`
	StrongProviders []string `json:"strongProviders"`
}

